-- ============================================================================
-- عنقود الصحة والتأمين: 20 صفحة ← 13 (2026-08-06)
-- ============================================================================
-- لا كشف مدوّياً هنا. هذا العنقود هو ببساطة حيث كُتبت الصفحة نفسها أكثر من
-- مرّة، ثمّ كُتبت نسخة طويلة جيّدة ولم تُحذف القصيرة.
--
-- ثلاث صفحات منفصلة عن تأمين الزلازل الإجباري (DASK). واثنتان عن تأمين
-- السيارة، وليست إحداهما الصفحة ذات الـ1,025 كلمة التي تشرح التعرفة فعلاً.
-- واثنتان عن e-Nabız إحداهما 24 كلمة. واثنتان عن حجز موعد المستشفى. وأربع
-- صفحات قصيرة تعيد ما يقوله عمود SGK/GSS ذو الـ591 كلمة.
--
-- وكل دمج يتبع القاعدة التي أظهرها عنقود الجنسية ويتحقّق منها هذا الملف:
-- الباقية هي الأطول متناً، لأنّ عناصر القوائم تُنقل ثمّ تُحذف الصفحة. وهذا
-- يقلب الاختيار البديهي مرّتين هنا — صفحتا تأمين السيارة تذهبان إلى صفحة
-- التعرفة لا إلى بعضهما، وصفحة حجز الموعد تذهب إلى دليل MHRS رغم أنّ لها
-- قراءات أكثر منه.
--
-- وحدّان فُحصا ولم يُفترضا:
--   • GSS ليس تأميناً خاصاً. صفحة «أسعار السيكورتا» ذات الـ87 كلمة تتحدّث عن
--     البوليصة الخاصة التي يطلبها ملفّ الإقامة، مسعّرةً بالفئة العمرية — منتج
--     مختلف عن نظام GSS الحكومي، فلا تُدمج فيه رغم اشتراك الكلمة. تبقى، وتبقى
--     موسومة: 87 كلمة وجدول أسعار بلا مصدر.
--   • kimlik-work-and-sgk مصنّفة تحت الصحة وهي عن العمل بلا إذن. تذهب إلى عمود
--     إذن العمل، لا إلى صفحة تأمين.
--
-- ومتروك لجولة مستقلّة عن قصد: صفحات السياحة العلاجية الثلاث. كلٌّ منها بين 56
-- و74 كلمة وبلا أي مصدر، وتحمل نطاقات أسعار بالدولار لعمليات الأسنان والعيون.
-- ذلك يحتاج قراراً في الإسناد لا دمجاً، وإنجازه على عجل هنا سيكرّر الخطأ الذي
-- صحّحه عنقود التأشيرات للتوّ.
--
-- شغّله بعد اكتمال نشر الشيفرة (التحويلات في next.config.ts).
-- ============================================================================

-- dask-earthquake-insurance  ←  2 صفحة
UPDATE articles SET
    documents = ARRAY['رقم الطابو أو رقم التأسيسات (DASK/UAVT No)', 'بيانات المبنى: سنة البناء، عدد الطوابق، المساحة بالمتر المربع', 'الهوية/بطاقة الإقامة']::text[],
    steps = ARRAY['احسب القسط عبر الحاسبة الرسمية على dask.gov.tr', 'اشترِ البوليصة من بنك أو شركة تأمين أو وكيل DASK', 'قدّم البوليصة عند معاملة الطابو أو اشتراك الكهرباء/الماء', 'جدّد التأمين كل عام قبل انتهائه', 'استخدم رقم البوليصة عند فتح/نقل العدادات إذا طُلب منك ذلك.', 'عند الضرر: وثّق الصور والفيديو بسرعة.', 'تابع التقييم والتعويض حتى الإغلاق.']::text[],
    tips = ARRAY['DASK لا يغطي الأثاث — أضف Konut Sigortası لتغطية المحتويات', 'احتفظ برقم البوليصة فستحتاجه لكل معاملة مرافق', 'تأكد من صحة مساحة العقار ونوعه لأن ذلك يؤثر على السعر والتغطية.']::text[],
    last_update = CURRENT_DATE
WHERE slug = 'dask-earthquake-insurance';

-- zorunlu-trafik-sigortasi-tavan-basamak-2026  ←  2 صفحة
UPDATE articles SET
    documents = ARRAY['رقم لوحة السيارة (Plaka)', 'رخصة القيادة أو رقم الهوية / رقم هوية الأجنبي (T.C./Yabancı Kimlik No)', 'أوراق تسجيل المركبة (Ruhsat)', 'للمركبات ذات اللوحة السورية/المؤقتة: وثيقة التسجيل أو اللوحة المؤقتة (geçici plaka) وبيانات المالك', 'حساب e-Devlet للاستعلام عن درجة الخصم']::text[],
    steps = ARRAY['استعلم أولاً عن درجتك الحالية (Basamak) عبر e-Devlet أو نظام SBM باستخدام رقم اللوحة ورقم هويتك.', 'تأكّد من نوع مركبتك وولاية تسجيل لوحتك، فكلاهما يدخل في حساب السعر الأعلى (Tavan).', 'قارن عروض أكثر من شركة تأمين؛ جميعها لا يمكنها تجاوز السقف، لكن كثيراً منها يعرض أقل منه.', 'تحقّق أنّ العرض يطبّق درجة الخصم الصحيحة الخاصة بك؛ إن ظهر القسط أعلى من المتوقّع فقد تكون الدرجة احتُسبت خطأ.', 'أصدر البوليصة باسم المالك المسجّل نفسه حتى تُراكم درجة الخصم لصالحك أنت.', 'جدّد البوليصة في موعدها دون انقطاع طويل حتى لا تخسر درجتك المكتسبة.', 'للوحة السورية/الأجنبية: تأكّد أنّ التأمين صادر وساري في تركيا قبل القيادة.', 'اقرأ بنود البوليصة: حدود التغطية، التحمل (Muafiyet)، مساعدة الطريق، تغطية الزجاج/السرقة/الكوارث.', 'في حال حادث: صور الموقع، اتصل بالشرطة عند الحاجة، وابدأ إجراءات “محضر حادث/كازا” حسب النظام.']::text[],
    tips = ARRAY['الحادث الصغير قد يكلّفك أكثر من قيمته على المدى الطويل: النزول درجة أو درجتين يرفع أقساط السنوات القادمة، ففكّر قبل فتح ملف تعويض على ضرر بسيط.', 'درجة الخصم تتبعك أنت لا السيارة؛ إذا غيّرت سيارتك تنتقل درجتك، لكن لا تشترِ خصم البائع عند شراء سيارة مستعملة.', 'لا تدع بوليصتك تنقطع مدّة طويلة؛ الانقطاع قد يُنزلك درجات ويلغي سنوات من الخصم.', 'الأرقام (السعر الأعلى ونسب الخصم) قابلة للتغيّر شهرياً وبقرارات الهيئة؛ لا تعتمد على رقم قديم رأيته في إعلان.', 'احتفظ بسجل نظيف بلا حوادث خمس سنوات في الدرجة 7 للوصول إلى خصم 50% في الدرجة 8.', 'القيادة بلا تأمين إجباري ساري تعني غرامة وحجز المركبة وتحمّلك أنت لكامل تعويض الحادث.', 'اسأل عن الورش المعتمدة وحدود التعويض.']::text[],
    last_update = CURRENT_DATE
WHERE slug = 'zorunlu-trafik-sigortasi-tavan-basamak-2026';

