    documents = ARRAY['رقم الكملك (يبدأ بـ 99) أو الإقامة', 'حساب e-Devlet مفعّل (للحجز عبر الموقع)', 'رقم هاتف تركي مفعّل (لتأكيد SMS)', 'عنوان محدّث في قاعدة بيانات SGK']::text[],
    steps = ARRAY['الموقع الرسمي: mhrs.gov.tr — تسجيل دخول بـ e-Devlet', 'التطبيق الجوّال: MHRS Mobil (iOS + Android)', 'الخط الهاتفي: ALO 182 — يعمل بالعربية + التركية + الإنجليزية + الروسية', 'تحتاج رقم أجنبي يبدأ بـ 99 (السوريون تحت الكملك مؤهلون)', 'احجز قبل 30 يوماً • أكّد قبل 20:00 من اليوم السابق وإلا يُلغى آلياً']::text[],
    tips = ARRAY['استخدم ALO 182 بالعربية إذا كنت تجد صعوبة في التركية — مشغّلون عرب يساعدونك', 'حمّل التطبيق المحمول للتنبيهات قبل الموعد', 'احجز موعد طبيب أسرتك دائماً قبل المستشفى — قد يحلّ مشكلتك بدون إحالة', 'إن لم تستطع الحضور، ألغِ قبل 20:00 من اليوم السابق لتفادي حظر 15 يوماً', 'احفظ رقم الموعد ورقم الطابور — تحتاجهما في المستشفى', 'تجنب الغياب عن الموعد دون إلغاء؛ تكرار الغياب قد يسبب قيوداً على الحجز.']::text[],
    last_update = CURRENT_DATE
WHERE slug = 'mhrs-guide-syrians-arabs-2026';

-- sgk-gss-health-insurance-turkey-2026  ←  2 صفحة
UPDATE articles SET
    documents = ARRAY['جواز السفر (الأصل + صورة)', 'إقامة سارية المفعول أو بطاقة الحماية المؤقتة', 'رقم الهوية الأجنبية (Yabancı Kimlik Numarası)', 'صورة شخصية', 'إثبات عنوان السكن (İkametgah Belgesi)']::text[],
    steps = ARRAY['تأكد إذا كنت ملزم بالتسجيل بـ GSS (بعد سنة إقامة متواصلة)', 'ألغِ أي تأمين خاص إذا كنت تنوي تنتقل لـ GSS', 'روح لأقرب مكتب SGK مع جوازك وإقامتك، أو قدّم عبر e-Devlet', 'ادفع الاشتراك الشهري (حوالي 1,982 ليرة لعام 2026)', 'استخدم التأمين فوراً بالمستشفيات الحكومية بتقديم رقم هويتك', 'تابع ديونك بشكل شهري عبر SGK GSS Borç Döküm على e-Devlet', 'راجع الاستثناءات: ما الذي لا يغطيه التأمين (أسنان/حمل/أمراض مزمنة) لتفادي المفاجآت.', 'ابحث عن خدمة “SGK Tescil ve Hizmet Dökümü / Hizmet Dökümü”.']::text[],
    tips = ARRAY['لا تتأخر بالدفع أكتر من 60 يوم — رح تخسر التغطية الصحية بالكامل', 'إذا كنت سوري ودخلك محدود، قدّم طلب إعفاء فوراً عبر إدارة الهجرة', 'احتفظ بتأمين خاص بسيط بجانب GSS للمستشفيات الخاصة', 'تأكد من فحص ديونك بانتظام عبر e-Devlet لتجنب المفاجآت', 'لو عندك عائلة، كل فرد لازم يكون مسجل بشكل منفصل', 'لا تخلط بين تأمين الإقامة والتأمين العلاجي القوي؛ اقرأ التغطية قبل الشراء.', 'لا تعتمد على كلام صاحب العمل؛ البيان هو الدليل الرسمي.']::text[],
    last_update = CURRENT_DATE
WHERE slug = 'sgk-gss-health-insurance-turkey-2026';

