-- work-permit-turkey-2026  ←  1 صفحة
UPDATE articles SET
    documents = ARRAY['جواز سفر ساري أو بطاقة حماية مؤقتة (للسوريين)', 'صور شخصية بيومترية', 'شهادات تعليمية أو خبرة مهنية مصدّقة ومترجمة', 'عقد عمل موقّع من صاحب العمل والموظف', 'السجل التجاري للشركة', 'بيان الضمان الاجتماعي SGK للشركة', 'كشف حساب الشركة البنكي', 'تصريح الميزانية الأخيرة للشركة']::text[],
    steps = ARRAY['تأكد إنك مستوفي الشروط (إقامة، وثائق، خبرة)', 'صاحب العمل يفتح حساب على eizin.csgb.gov.tr', 'صاحب العمل يعبّئ النموذج ويرفع الوثائق', 'ادفع الرسوم المطلوبة', 'انتظر مراجعة وزارة العمل (30 يوم عادةً)', 'بعد القبول، استلم بطاقة إذن العمل', 'صاحب العمل يقدم طلب التجديد عبر e-İzin قبل 60 يوماً', 'راقب دفع SGK شهرياً عبر e-Devlet (Hizmet Dökümü) واحتفظ بنسخ PDF كإثبات.']::text[],
    tips = ARRAY['إذن العمل مرتبط بصاحب عمل محدد — لو غيّرت شغلك لازم تقدّم من جديد', 'للسوريين: إذن العمل ما بيسمح بالسفر خارج تركيا', 'تأكد إنه صاحب العمل عنده نسبة الأتراك الكافية (5 أتراك لكل أجنبي)', 'لا تشتغل بدون إذن عمل — الغرامات على صاحب العمل والموظف كبيرة', 'بعد 8 سنوات عمل قانوني متواصل تقدر تحصل على إذن عمل دائم', 'صاحب العمل يجب أن يكون مسجّلاً في SGK (الضمان الاجتماعي)', 'السوريون يمكنهم الحصول على إذن عمل مجاني عبر İŞKUR', 'ترجم شهادتك عند مترجم محلّف (Yeminli Tercüman) وصدّقها من النوتر', 'إذا ليس لديك شهادة جامعية، شهادة الخبرة المهنية قد تُقبل', 'لا تدفع لوسطاء يعدون بإذن عمل سريع بدون شركة حقيقية؛ هذا يعرضك لمشاكل قانونية.']::text[],
    last_update = CURRENT_DATE
WHERE slug = 'work-permit-turkey-2026';

-- سدّ حقل المصدر --------------------------------------------------------
UPDATE articles SET source = 'مؤسسة الضمان الاجتماعي التركية (sgk.gov.tr) وبوّابة e-Devlet — خدمات تسجيل المُعالين ضمن التأمين الصحي.', last_update = CURRENT_DATE
WHERE slug = 'sgk-add-family-members-health-insurance-2026' AND coalesce(trim(source), '') = '';

-- الصفحات المدموجة تُحذف بعد نقل ما يستحقّ
DELETE FROM articles WHERE slug IN ('earthquake-insurance', 'housing-advanced-dask', 'car-insurance', 'auto-insurance-trafik-vs-kasko', 'e-nabiz-guide', 'hospital-appointment', 'health-insurance-types', 'edevlet-sgk-dokumu', 'kimlik-health-services', 'kimlik-work-and-sgk');

-- ═══════════════════════════════════════════════════════════════════════════
-- التحقّق — الأول 7 صفوف، والثاني صفر
SELECT slug, coalesce(array_length(steps,1),0) AS steps,
       coalesce(array_length(tips,1),0) AS tips, last_update
FROM articles WHERE slug IN ('dask-earthquake-insurance', 'zorunlu-trafik-sigortasi-tavan-basamak-2026', 'e-nabiz-electronic-health-record-2026', 'mhrs-guide-syrians-arabs-2026', 'sgk-gss-health-insurance-turkey-2026', 'syria-temporary-protection-health-2026', 'work-permit-turkey-2026') ORDER BY slug;

SELECT slug FROM articles WHERE slug IN ('earthquake-insurance', 'housing-advanced-dask', 'car-insurance', 'auto-insurance-trafik-vs-kasko', 'e-nabiz-guide', 'hospital-appointment', 'health-insurance-types', 'edevlet-sgk-dokumu', 'kimlik-health-services', 'kimlik-work-and-sgk');

SELECT slug, (coalesce(trim(source), '') <> '') AS له_مصدر
FROM articles WHERE slug = 'sgk-add-family-members-health-insurance-2026';
